#!/usr/bin/env node

const { sendMessage } = require('../event_handler/tools/telegram.js');
const fs = require('fs');
const path = require('path');

// Read the briefing
const briefingPath = path.join(__dirname, 'sterling_briefing.md');
const briefing = fs.readFileSync(briefingPath, 'utf-8');

// Convert markdown to HTML for Telegram
function markdownToHtml(md) {
  let html = md;

  // Headers
  html = html.replace(/^# (.*?)$/gm, '<b>$1</b>');
  html = html.replace(/^## (.*?)$/gm, '<b>$1</b>');
  html = html.replace(/^### (.*?)$/gm, '<b>$1</b>');

  // Bold
  html = html.replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');

  // Code blocks (inline)
  html = html.replace(/`(.*?)`/g, '<code>$1</code>');

  // Preserve newlines
  html = html.replace(/\n/g, '\n');

  return html;
}

async function main() {
  // Try to get credentials from environment or arguments
  const botToken = process.env.TELEGRAM_BOT_TOKEN || process.argv[2];
  const chatId = process.env.TELEGRAM_CHAT_ID || process.argv[3];

  if (!botToken || !chatId) {
    console.error('❌ Missing Telegram credentials');
    console.error('Usage: node send_briefing.js [BOT_TOKEN] [CHAT_ID]');
    console.error('Or set TELEGRAM_BOT_TOKEN and TELEGRAM_CHAT_ID environment variables');
    console.error('\n📄 Briefing saved to:', briefingPath);
    process.exit(1);
  }

  const htmlMessage = markdownToHtml(briefing);

  try {
    console.log('📤 Sending Sterling Intelligence Briefing to Telegram...');
    await sendMessage(botToken, chatId, htmlMessage);
    console.log('✅ Briefing sent successfully!');
  } catch (error) {
    console.error('❌ Error sending message:', error.message);
    console.error('\n📄 Briefing saved to:', briefingPath);
    process.exit(1);
  }
}

main();

